n=len(target)

def make_start(seedn):
    random.seed(seedn)
    pair=[-1]*n; stack=[]
    for i,c in enumerate(target):
        if c=='(': stack.append(i)
        elif c==')':
            j=stack.pop(); pair[j]=i; pair[i]=j
    seq=['A']*n
    for i in range(n):
        if pair[i]>i:
            pc=random.choice(['GC','CG','AU','UA','GU','UG'])
